import { describe, expect, it } from "vitest"
import { buildInbox } from "./inbox"
import { QuoteStatus } from "../../types/work-quotes"
import { SupplierBillStatus } from "../../types/work-purchases"

const base = {
  rights: { approveTime: false, invoices: true, hr: false, purchases: true },
  employees: [{ id: "omar", name: "Omar Idrissi" }, { id: "lina", name: "Lina Moreau" }] as never[],
  reviews: [], entries: [], leave: [], expenses: [], invoices: [], documents: [], tasks: [],
  today: "2026-10-28",
}
const titles = (employeeId: string, extra: object) => buildInbox({ ...base, viewer: { employeeId, isAdmin: false }, ...extra }).map((i) => i.title)

describe("new bell items (A4.2)", () => {
  it("tells the owner about deals that stopped moving", () => {
    const deals = [{ id: "d1", title: "Audit", clientId: "c", amount: 1, stage: "proposal", stageSince: "2026-09-01", ownerId: "omar", expectedClose: "2026-12-01", createdAt: "2026-09-01T00:00:00Z" }] as never[]
    expect(titles("omar", { deals })).toContain("inboxStaleDeals")
    expect(titles("lina", { deals })).not.toContain("inboxStaleDeals")
  })

  it("lists sent quotes expiring within 3 days, not later ones or drafts", () => {
    const q = (id: string, validUntil: string, status = QuoteStatus.SENT) => ({ id, validUntil, status }) as never
    const items = buildInbox({ ...base, viewer: { employeeId: "lina", isAdmin: false }, quotes: [q("a", "2026-10-30"), q("b", "2026-11-15"), q("c", "2026-10-29", QuoteStatus.DRAFT)] })
    expect(items.find((i) => i.title === "inboxQuotesExpiring")?.values.count).toBe(1)
  })

  it("lists approved, unpaid supplier bills due within 7 days", () => {
    const bill = (id: string, dueDate: string, status = SupplierBillStatus.APPROVED) => ({ id, dueDate, status, lines: [{ quantity: 1, unitPrice: 100 }], taxRate: 20, payments: [] }) as never
    const items = buildInbox({ ...base, viewer: { employeeId: "lina", isAdmin: false }, supplierBills: [bill("a", "2026-11-02"), bill("b", "2026-12-30"), bill("c", "2026-10-30", SupplierBillStatus.SUBMITTED)] })
    expect(items.find((i) => i.title === "inboxBillsDue")?.values.count).toBe(1)
  })

  it("gives each person the open action items that @mention them", () => {
    const projectPages = [{ id: "pg", projectId: "prj", title: "Beta planning", body: "- [x] Done @Lina Moreau\n- [ ] Write scenarios @Omar Idrissi\n- [ ] Draft copy @Lina Moreau\n- [ ] Linked @Lina Moreau ORB-01#4" }] as never[]
    const lina = buildInbox({ ...base, viewer: { employeeId: "lina", isAdmin: false }, projectPages }).find((i) => i.title === "inboxActionItems")
    expect(lina).toMatchObject({ values: { count: 1, page: "Beta planning" }, href: "/dashboard/projects/prj?tab=pages" })
    expect(titles("omar", { projectPages })).toContain("inboxActionItems")
  })
})
